text 2 2 "야전 침대. 담요 밑에 손전등 건전지 껍데기가 수북하다." h=2
npc N-UG-001 5 4 S bark="터널이 우는 날은 들어가지 마. 물 들어온다."
prop w_chalk_height 9 3
text 9 4 "키 재기 낙서. 분필 눈금 다섯 — '로아 9 · 10 · 11 · 12'. 맨 위 눈금엔 물음표만." scene=NT_HEIGHT
# ---------------------------------------------------------------- 2077 대피 방송 스피커
prop w_speaker 12 3
text 12 4 "벽 스피커. 2077년 대피 방송이 녹음돼 있던 곳. 망이 찢겨 안에 쥐 둥지가 보인다."
# ---------------------------------------------------------------- ② 정비 측실(조명 회로 함 — UG-H01)
prop w_circuit_box 16 0 cond="U02_LIGHT == 0"
prop w_circuit_box 16 0 state=sadang cond="U02_LIGHT == 1"
prop w_circuit_box 16 0 state=full cond="U02_LIGHT == 2"
prop w_circuit_box 16 0 state=cut cond="U02_LIGHT == 3"
text 16 1 "조명 회로 함. 차단기 둘 — '사당 측' · '남태령 측'. 문이 반쯤 열려 있다." scene=NT_CIRCUIT
prop tool_chest 18 2
box 18 2 toolbox name="정비 공구함"
prop rathole 14 4
text 15 2 "정비 측실. 바닥에 2077년 작업 일지가 젖어 붙었다. 마지막 줄 — '23:29 정전. 비상등 30%. 복구 인원 없음.'" w=2
# ---------------------------------------------------------------- 터널 등(회로 상태 — 사당 쪽만 · 끝까지)
prop w_tunnel_lamp 8 3 cond="U02_LIGHT == 0 or U02_LIGHT == 3"
prop w_tunnel_lamp 8 3 state=on cond="U02_LIGHT == 1 or U02_LIGHT == 2"
prop w_tunnel_lamp 22 3 cond="U02_LIGHT == 0 or U02_LIGHT == 3"
prop w_tunnel_lamp 22 3 state=on cond="U02_LIGHT == 1 or U02_LIGHT == 2"
prop w_tunnel_lamp 28 3 cond="U02_LIGHT == 0 or U02_LIGHT == 3"
prop w_tunnel_lamp 28 3 state=on cond="U02_LIGHT == 1 or U02_LIGHT == 2"
prop w_tunnel_lamp 40 3 cond="U02_LIGHT != 2"
prop w_tunnel_lamp 40 3 state=on cond="U02_LIGHT == 2"
prop w_tunnel_lamp 44 3 cond="U02_LIGHT != 2"
prop w_tunnel_lamp 44 3 state=on cond="U02_LIGHT == 2"
prop w_tunnel_lamp 58 3 cond="U02_LIGHT != 2"
prop w_tunnel_lamp 58 3 state=on cond="U02_LIGHT == 2"
text 22 4 "터널 등. 철망 덮개 속 형광등." cond="U02_LIGHT == 0 or U02_LIGHT == 3"
text 22 4 "터널 등이 켜졌다. 레일이 물비늘처럼 반짝인다 — 사당 쪽으로." cond="U02_LIGHT == 1 or U02_LIGHT == 2"
# ---------------------------------------------------------------- 반로아 분필 화살표(안내를 받은 뒤 — 쥐 둥지 · 물 고인 데를 피해 가는 길)
prop w_chalk_roa 24 3 cond="U02_GUIDE >= 1"
text 24 4 "분필 화살표. '→ 로아.' 옆에 쥐 그림에 가위표 — 둥지 쪽은 가지 말라는 뜻이다." cond="U02_GUIDE >= 1"
prop w_chalk_roa 41 3 cond="U02_GUIDE >= 1"
text 41 4 "분필 화살표. '→ 로아.' 침목 무너진 데는 위쪽 레일 곁으로." cond="U02_GUIDE >= 1"
# ---------------------------------------------------------------- 발목 물(배수 막힘)
text 23 9 "발목까지 고인 물. 배수구가 쓰레기로 막혔다. 바닥 어딘가에서 찍찍 소리." w=3
# ---------------------------------------------------------------- 멈춘 막차(2077 고리 ①)
prop train_car4 30 5
text 30 7 "멈춘 전동차. 행선 표시기에 붉은 글씨 '막차'가 굳었다. 문 하나가 반쯤 열려 있다." w=8 scene=NT_CAR
